conditionals.code:
my $score = 85;

if ($score >= 90) {
    print "A\n";
} elsif ($score >= 80) {
    print "B\n";
} else {
    print "C\n";
}

# Postfix conditionals
print "Pass\n" if $score >= 50;
print "Fail\n" unless $score >= 50;

for_loop.code:
my @items = ('a', 'b', 'c');

# foreach loop (idiomatic)
foreach my $item (@items) {
    print "$item\n";
}

# C-style for loop
for (my $i = 0; $i < @items; $i++) {
    print $items[$i] . "\n";
}

while_loop.code:
my $count = 0;

while ($count < 5) {
    print "$count\n";
    $count++;
}

# Until loop
until ($count == 0) {
    $count--;
}

functions.code:
# Function signatures (Perl 5.36+ default)
use feature 'signatures';
no warnings 'experimental::signatures';

sub add($x, $y) {
    return $x + $y;
}

# Traditional subroutine
sub greet {
    my ($name, $greeting) = @_;
    $greeting //= 'Hello';
    return "$greeting, $name!";
}

arrays.code:
my @numbers = (1, 2, 3);
push @numbers, 4;

# Array functions
my @doubled = map { $_ * 2 } @numbers;
my @evens = grep { $_ % 2 == 0 } @numbers;

# Array size
my $size = scalar @numbers;

maps.code:
my %user_roles = (
    alice => 'admin',
    bob   => 'user'
);

$user_roles{charlie} = 'guest';

if (exists $user_roles{alice}) {
    print $user_roles{alice};
}

# Iterate over keys and values
while (my ($k, $v) = each %user_roles) {
    print "$k: $v\n";
}

error_handling.code:
# eval for exception handling
eval {
    die "Something went wrong\n";
};
if ($@) {
    warn "Caught: $@";
}

# Try/Catch (Perl 5.34+ with feature 'try')
use feature 'try';
no warnings 'experimental::try';

try {
    die "Fatal error";
} catch ($e) {
    warn "Caught error: $e";
}

